fn record_trace_label_is_safe(label: &str) -> bool {
    !label.is_empty()
        && label
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte == b'-')
}

/// Emit only an allowlisted, static recorder progress label when explicitly
/// requested. Labels must never carry remote values or error details.
fn record_trace(label: &'static str) {
    debug_assert!(RECORD_TRACE_LABELS.contains(&label));
    debug_assert!(record_trace_label_is_safe(label));
    if std::env::var("ELASTICCTL_RECORD_TRACE").ok().as_deref() == Some("1") {
        eprintln!("record step: {label}");
    }
}

/// Recorder errors can carry live object ids in a server message or body.
/// Preserve only their classification and status at public error boundaries.
fn safe_recording_transport_error(
    context: &'static str,
    error: elasticctl_core::Error,
) -> elasticctl_core::Error {
    match error.http_status {
        Some(status) => elasticctl_core::Error::with_status(error.kind, status, context),
        None => elasticctl_core::Error::new(error.kind, context),
    }
}

fn safe_recording_error_summary(error: &elasticctl_core::Error) -> String {
    let status = error
        .http_status
        .map_or_else(|| "none".to_string(), |status| status.to_string());
    format!("class={} status={status}", error.kind.as_str())
}

fn dashboard_transport<T>(
    context: &'static str,
    result: elasticctl_core::Result<T>,
) -> elasticctl_core::Result<T> {
    result.map_err(|error| safe_recording_transport_error(context, error))
}

/// The only recorder flavor that starts headless needs a profile activation
/// before the later alert-assignment probe can resolve an assignee. Keep the
/// decision pure so tests never race on process environment variables.
struct TraditionalRecorderLogin<'a> {
    username: &'a str,
    password: &'a str,
}

fn traditional_recorder_login_inputs<'a>(
    flavor: Option<&str>,
    username: Option<&'a str>,
    password: Option<&'a str>,
) -> elasticctl_core::Result<Option<TraditionalRecorderLogin<'a>>> {
    if flavor != Some("traditional") {
        return Ok(None);
    }
    let username = username
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            recording_error("ELASTICCTL_USERNAME is required for traditional fixture recording")
        })?;
    let password = password
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            recording_error("ELASTICCTL_PASSWORD is required for traditional fixture recording")
        })?;
    Ok(Some(TraditionalRecorderLogin { username, password }))
}

async fn activate_traditional_recorder_profile() -> elasticctl_core::Result<()> {
    let flavor = std::env::var("ELASTICCTL_FIXTURE_FLAVOR").ok();
    let username = std::env::var("ELASTICCTL_USERNAME").ok();
    let password = std::env::var("ELASTICCTL_PASSWORD").ok();
    let login = traditional_recorder_login_inputs(
        flavor.as_deref(),
        username.as_deref(),
        password.as_deref(),
    )?;
    let Some(login) = login else {
        return Ok(());
    };
    let kibana_url = std::env::var("ELASTICCTL_KIBANA_URL").map_err(|_| {
        recording_error("ELASTICCTL_KIBANA_URL is required for traditional fixture recording")
    })?;
    activation::activate_profile(&kibana_url, login.username, login.password)
        .await
        .map_err(|error| {
            safe_recording_transport_error("traditional profile activation failed", error)
        })
}

async fn recorder_get_data_view_default(
    t: &elasticctl_core::Transport,
    context: &'static str,
) -> elasticctl_core::Result<Value> {
    t.get("/api/data_views/default")
        .await
        .map_err(|error| safe_recording_transport_error(context, error))
}

async fn recorder_post_data_view_default(
    t: &elasticctl_core::Transport,
    body: &Value,
    context: &'static str,
) -> elasticctl_core::Result<Value> {
    t.post("/api/data_views/default", Some(body))
        .await
        .map_err(|error| safe_recording_transport_error(context, error))
}

fn has_marker_tags(value: &Value) -> bool {
    let tags = value.get("tags").and_then(Value::as_array);
    MARKER_TAGS.iter().all(|tag| {
        tags.is_some_and(|tags| tags.iter().any(|candidate| candidate.as_str() == Some(tag)))
    })
}

fn owns_rule(value: &Value) -> bool {
    value.get("rule_id").and_then(Value::as_str) == Some(RULE_ID) && has_marker_tags(value)
}

fn owns_list(value: &Value) -> bool {
    value.get("list_id").and_then(Value::as_str) == Some(LIST_ID)
        && value
            .get("namespace_type")
            .and_then(Value::as_str)
            .unwrap_or("single")
            == NAMESPACE_TYPE
        && has_marker_tags(value)
}

fn owns_item(value: &Value) -> bool {
    value.get("item_id").and_then(Value::as_str) == Some(ITEM_ID)
        && value.get("list_id").and_then(Value::as_str) == Some(LIST_ID)
        && value
            .get("namespace_type")
            .and_then(Value::as_str)
            .unwrap_or("single")
            == NAMESPACE_TYPE
        && has_marker_tags(value)
}

fn integration_response_item(
    value: &Value,
) -> elasticctl_core::Result<&serde_json::Map<String, Value>> {
    value
        .get("item")
        .and_then(Value::as_object)
        .ok_or_else(|| recording_error("integration policy response must contain an item object"))
}

fn is_optional_false(item: &serde_json::Map<String, Value>, fields: &[&str]) -> bool {
    fields.iter().all(|field| {
        matches!(
            item.get(*field),
            None | Some(Value::Null) | Some(Value::Bool(false))
        )
    })
}

fn is_optional_null(item: &serde_json::Map<String, Value>, fields: &[&str]) -> bool {
    fields
        .iter()
        .all(|field| matches!(item.get(*field), None | Some(Value::Null)))
}

fn is_optional_empty_object(item: &serde_json::Map<String, Value>, fields: &[&str]) -> bool {
    fields.iter().all(|field| match item.get(*field) {
        None | Some(Value::Null) => true,
        Some(Value::Object(values)) => values.is_empty(),
        Some(_) => false,
    })
}

fn is_optional_empty_array(item: &serde_json::Map<String, Value>, fields: &[&str]) -> bool {
    fields.iter().all(|field| match item.get(*field) {
        None | Some(Value::Null) => true,
        Some(Value::Array(values)) => values.is_empty(),
        Some(_) => false,
    })
}

fn is_optional_empty_string(item: &serde_json::Map<String, Value>, field: &str) -> bool {
    match item.get(field) {
        None | Some(Value::Null) => true,
        Some(Value::String(value)) => value.is_empty(),
        Some(_) => false,
    }
}

fn normalized_active_space(active_space: &str) -> &str {
    if active_space.is_empty() {
        "default"
    } else {
        active_space
    }
}

fn has_only_active_spaces(
    item: &serde_json::Map<String, Value>,
    fields: &[&str],
    active_space: &str,
) -> bool {
    let active_space = normalized_active_space(active_space);
    fields.iter().all(|field| match item.get(*field) {
        None | Some(Value::Null) => true,
        Some(Value::Array(spaces)) => spaces
            .iter()
            .all(|space| space.as_str() == Some(active_space)),
        Some(_) => false,
    })
}

fn marker_integration_package_matches(
    item: &serde_json::Map<String, Value>,
    expected_version: &str,
) -> bool {
    !expected_version.trim().is_empty()
        && item
            .get("package")
            .and_then(Value::as_object)
            .is_some_and(|package| {
                package.get("name").and_then(Value::as_str) == Some(INTEGRATION_POLICY_PACKAGE)
                    && package.get("version").and_then(Value::as_str) == Some(expected_version)
            })
}

/// The bootstrap marker exists only long enough to obtain the simplified map
/// that Fleet materializes. Its map cannot be known before the write. Every
/// recorded or cleanup-owned policy after that point must instead retain the
/// exact captured map.
#[derive(Clone, Copy)]
enum MarkerIntegrationInputs<'a> {
    Empty,
    Exact(&'a Map<String, Value>),
    BootstrapObject,
}

#[derive(Clone, Copy)]
struct MarkerResponseExpectation<'a> {
    description: Option<&'a str>,
    inputs: MarkerIntegrationInputs<'a>,
}

#[derive(Clone, Copy)]
struct IntegrationFixtureContext<'a> {
    active_space: &'a str,
    nonce: &'a str,
    expected_inputs: &'a Map<String, Value>,
}

fn marker_integration_inputs_match(
    item: &Map<String, Value>,
    expected: MarkerIntegrationInputs<'_>,
) -> bool {
    let Some(inputs) = item.get("inputs").and_then(Value::as_object) else {
        return false;
    };
    match expected {
        MarkerIntegrationInputs::Empty => inputs.is_empty(),
        MarkerIntegrationInputs::Exact(expected) => inputs == expected,
        MarkerIntegrationInputs::BootstrapObject => true,
    }
}

/// Prove that one package-policy item is still the recorder's exact portable
/// marker. List rows use this directly; single responses must pass the strict
/// envelope validator below as well.
fn validate_marker_integration_item_with_nonce_and_inputs(
    item: &Map<String, Value>,
    id: &str,
    expected_version: &str,
    active_space: &str,
    nonce: &str,
    expected_description: Option<&str>,
    expected_inputs: MarkerIntegrationInputs<'_>,
) -> elasticctl_core::Result<()> {
    let created_description = marker_integration_description(nonce);
    let updated_description = marker_integration_updated_description(nonce);
    let description_matches = match expected_description {
        Some(expected) => {
            (expected == created_description.as_str() || expected == updated_description.as_str())
                && item.get("description").and_then(Value::as_str) == Some(expected)
        }
        None => matches!(
            item.get("description").and_then(Value::as_str),
            Some(description)
                if description == created_description || description == updated_description
        ),
    };
    let identity_matches = item.get("id").and_then(Value::as_str) == Some(id)
        && item.get("name").and_then(Value::as_str) == Some(INTEGRATION_POLICY_NAME)
        && item.get("namespace").and_then(Value::as_str) == Some(INTEGRATION_POLICY_NAMESPACE)
        && !nonce.trim().is_empty()
        && description_matches
        && item
            .get("policy_ids")
            .and_then(Value::as_array)
            .is_some_and(|ids| {
                ids.len() == 1 && ids[0].as_str() == Some(INTEGRATION_POLICY_PARENT_ID)
            })
        && match item.get("policy_id") {
            None | Some(Value::Null) => true,
            Some(Value::String(id)) => id == INTEGRATION_POLICY_PARENT_ID,
            Some(_) => false,
        }
        && marker_integration_package_matches(item, expected_version)
        && marker_integration_inputs_match(item, expected_inputs)
        && item.get("enabled").and_then(Value::as_bool) == Some(true)
        && is_optional_false(
            item,
            &[
                "is_managed",
                "supports_agentless",
                "supports_cloud_connector",
            ],
        )
        && is_optional_false(
            item,
            &["output_id", "cloud_connector_id", "cloud_connector_name"],
        )
        && is_optional_empty_array(item, &["secret_references"])
        && has_only_active_spaces(item, &["spaceIds", "space_ids"], active_space)
        && is_optional_empty_object(item, &["vars", "var_group_selections"])
        && is_optional_empty_string(item, "condition")
        && is_optional_empty_array(
            item,
            &["additional_datastreams_permissions", "global_data_tags"],
        );
    if identity_matches {
        Ok(())
    } else {
        Err(recording_error(
            "integration policy response did not preserve the marker identity",
        ))
    }
}

/// Prove that one live package-policy response is still the recorder's exact
/// portable marker. Every mutation and cleanup path calls this same validator
/// with the package version observed in the strict preflight inventory.
fn validate_marker_integration_with_nonce_and_inputs<'a>(
    value: &'a Value,
    id: &str,
    expected_version: &str,
    active_space: &str,
    nonce: &str,
    expected_description: Option<&str>,
    expected_inputs: MarkerIntegrationInputs<'_>,
) -> elasticctl_core::Result<&'a Map<String, Value>> {
    let item = integration_response_item(value)?;
    validate_marker_integration_item_with_nonce_and_inputs(
        item,
        id,
        expected_version,
        active_space,
        nonce,
        expected_description,
        expected_inputs,
    )?;
    Ok(item)
}

/// Create responses may omit `agents`, but every parent state that can lead to
/// a delete must additionally prove an empty attached-agent count below.
fn validate_marker_integration_parent_identity_with_nonce<'a>(
    value: &'a Value,
    active_space: &str,
    nonce: &str,
) -> elasticctl_core::Result<&'a serde_json::Map<String, Value>> {
    let item = integration_response_item(value).map_err(|_| {
        recording_error("integration policy parent response must contain an item object")
    })?;
    let identity_matches = item.get("id").and_then(Value::as_str)
        == Some(INTEGRATION_POLICY_PARENT_ID)
        && item.get("name").and_then(Value::as_str) == Some(INTEGRATION_POLICY_PARENT_NAME)
        && item.get("namespace").and_then(Value::as_str) == Some(INTEGRATION_POLICY_NAMESPACE)
        && item.get("description").and_then(Value::as_str)
            == Some(marker_integration_parent_description(nonce).as_str())
        && !nonce.trim().is_empty()
        && item
            .get("monitoring_enabled")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && item.get("inactivity_timeout").and_then(Value::as_u64)
            == Some(INTEGRATION_POLICY_PARENT_INACTIVITY_TIMEOUT)
        && is_optional_false(
            item,
            &[
                "is_default",
                "is_default_fleet_server",
                "has_fleet_server",
                "is_managed",
                "is_preconfigured",
                "supports_agentless",
                "is_verifier",
                "is_protected",
            ],
        )
        && is_optional_null(item, &["agentless"])
        && is_optional_null(
            item,
            &[
                "data_output_id",
                "monitoring_output_id",
                "download_source_id",
                "fleet_server_host_id",
                "required_versions",
            ],
        )
        && has_only_active_spaces(item, &["space_ids", "spaceIds"], active_space)
        && is_optional_empty_array(item, &["agent_features", "global_data_tags"])
        && is_optional_empty_object(
            item,
            &[
                "advanced_settings",
                "overrides",
                "monitoring_http",
                "monitoring_diagnostics",
            ],
        )
        && is_optional_false(item, &["keep_monitoring_alive", "monitoring_pprof_enabled"])
        && is_optional_null(item, &["unenroll_timeout"]);
    if identity_matches {
        Ok(item)
    } else {
        Err(recording_error(
            "integration policy parent did not preserve the marker identity",
        ))
    }
}

fn validate_marker_integration_parent_for_delete_with_nonce<'a>(
    value: &'a Value,
    active_space: &str,
    nonce: &str,
) -> elasticctl_core::Result<&'a serde_json::Map<String, Value>> {
    let item = validate_marker_integration_parent_identity_with_nonce(value, active_space, nonce)?;
    if item.get("agents").and_then(Value::as_u64) == Some(0) {
        Ok(item)
    } else {
        Err(recording_error(
            "integration policy parent did not preserve the marker identity",
        ))
    }
}

fn owns_scratch_index(value: &Value) -> bool {
    value["_source"][SCRATCH_MARKER].as_bool() == Some(true)
}

fn owns_search_index(value: &Value) -> bool {
    value["_source"]["marker"].as_str() == Some(SEARCH_MARKER)
}

fn owns_alert_rule(value: &Value) -> bool {
    value.get("rule_id").and_then(Value::as_str) == Some(ALERT_RULE_ID)
        && value
            .get("tags")
            .and_then(Value::as_array)
            .is_some_and(|tags| {
                tags.iter()
                    .any(|tag| tag.as_str() == Some(ALERT_MARKER_TAG))
            })
}

fn owns_alert_index(value: &Value) -> bool {
    value["_source"]["marker"].as_str() == Some(ALERT_MARKER_TAG)
}

/// True when a case create response proves the fixed marker identity: the
/// exact title AND the marker tag, mirroring `owns_rule`'s AND semantics.
fn owns_case(value: &Value) -> bool {
    value.get("title").and_then(Value::as_str) == Some(CASE_TITLE)
        && value
            .get("tags")
            .and_then(Value::as_array)
            .is_some_and(|tags| tags.iter().any(|tag| tag.as_str() == Some(CASE_TAG)))
}

/// The query filter that names every alert the probe rule produced.
fn alert_probe_filter() -> Value {
    json!({"term": {"kibana.alert.rule.rule_id": ALERT_RULE_ID}})
}

/// Every alert the probe rule produced that has not been closed. Closed
/// residue from an earlier run is the accepted deviation (spec section 9).
fn alert_probe_open_filter() -> Value {
    json!({
        "bool": {
            "filter": [alert_probe_filter()],
            "must_not": [{"term": {"kibana.alert.workflow_status": "closed"}}]
        }
    })
}

async fn require_no_open_marker_alerts(
    t: &elasticctl_core::Transport,
) -> elasticctl_core::Result<()> {
    let body = json!({"query": alert_probe_open_filter(), "size": 0, "track_total_hits": true});
    let response = t
        .post(elasticctl_api::alerts::SEARCH_PATH, Some(&body))
        .await?;
    let total = response
        .pointer("/hits/total/value")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if total > 0 {
        return Err(recording_error(format!(
            "refusing to record: {total} non-closed alert(s) already carry rule_id {ALERT_RULE_ID}"
        )));
    }
    Ok(())
}

/// Best-effort disable of the marker rule (idempotent: a rule that is
/// already gone or already disabled is not an error, so its result is
/// ignored), then close every marker alert by query, checking after each
/// attempt. Retries up to 5 times, 3 seconds apart, to absorb a rule
/// execution that was already in flight when disabled. Shared by
/// `record_alerts`'s own residue step and `cleanup`'s last-resort sweep.
async fn sweep_close_marker_alerts(t: &elasticctl_core::Transport) -> elasticctl_core::Result<()> {
    let _ = t
        .patch(
            "/api/detection_engine/rules",
            &json!({"rule_id": ALERT_RULE_ID, "enabled": false}),
        )
        .await;
    let close_query_request = json!({
        "query": alert_probe_filter(),
        "status": "closed",
        "conflicts": "abort",
        "reason": "automated_closure",
    });
    for _ in 0..5 {
        if require_no_open_marker_alerts(t).await.is_ok() {
            return Ok(());
        }
        t.post(
            elasticctl_api::alerts::STATUS_PATH,
            Some(&close_query_request),
        )
        .await
        .map_err(|error| {
            safe_recording_transport_error("close-by-query sweep retry failed", error)
        })?;
        tokio::time::sleep(std::time::Duration::from_secs(3)).await;
    }
    require_no_open_marker_alerts(t).await.map_err(|error| {
        safe_recording_transport_error("checking close-by-query sweep result failed", error)
    })
}

/// The `_find` filter that names every marker case: the fixed title AND the
/// fixed tag together, matching `owns_case`'s AND semantics.
fn case_marker_filter() -> elasticctl_api::cases_ops::CaseFilter {
    elasticctl_api::cases_ops::CaseFilter {
        search: Some(CASE_TITLE.to_string()),
        tag: Some(CASE_TAG.to_string()),
        ..Default::default()
    }
}

async fn find_marker_cases(
    t: &elasticctl_core::Transport,
) -> elasticctl_core::Result<(Vec<elasticctl_api::cases::Case>, u64)> {
    let query = elasticctl_api::cases_ops::find_query(
        &case_marker_filter(),
        1,
        elasticctl_api::cases_ops::PAGE_SIZE,
    );
    elasticctl_api::cases::find_page(t, &query).await
}

async fn require_no_marker_cases(t: &elasticctl_core::Transport) -> elasticctl_core::Result<()> {
    let (cases, total) = find_marker_cases(t).await?;
    if total > 0 || !cases.is_empty() {
        return Err(recording_error(format!(
            "refusing to record: {total} case(s) already carry title {CASE_TITLE:?} and tag \
             {CASE_TAG}. Manual remediation: find the id(s) via GET {}?{} then DELETE {} with \
             the matching ?ids=[...] query.",
            elasticctl_api::cases::FIND_PATH,
            elasticctl_api::cases_ops::find_query(
                &case_marker_filter(),
                1,
                elasticctl_api::cases_ops::PAGE_SIZE
            ),
            elasticctl_api::cases::CASES_PATH,
        )));
    }
    Ok(())
}

/// Delete every marker case found by title+tag, then re-verify none remain.
/// Cases tolerate zero residue (spec section 9) — unlike the alerts probe's
/// accepted closed-alert deviation, there is no "closed is fine" escape
/// hatch here. Shared by `record_cases`'s own delete step and `cleanup`'s
/// last-resort sweep.
async fn sweep_delete_marker_cases(t: &elasticctl_core::Transport) -> elasticctl_core::Result<()> {
    let (cases, _) = find_marker_cases(t).await?;
    let ids: Vec<String> = cases
        .into_iter()
        .filter(|c| c.title == CASE_TITLE && c.tags.iter().any(|tag| tag == CASE_TAG))
        .map(|c| c.id)
        .collect();
    if !ids.is_empty() {
        elasticctl_api::cases::delete(t, &ids).await?;
    }
    require_no_marker_cases(t).await
}

