fn integration_policy_exchange_fixture_in_space(
    name: &'static str,
    flavor: &str,
    version: &str,
    active_space: &str,
    nonce: &str,
    request: Value,
    body: Value,
) -> elasticctl_core::Result<RecordedFixture> {
    integration_policy_exchange_fixture_in_space_with_inputs(
        name,
        flavor,
        version,
        IntegrationFixtureContext {
            active_space,
            nonce,
            expected_inputs: &Map::new(),
        },
        request,
        body,
    )
}

fn integration_policy_exchange_fixture_in_space_with_inputs(
    name: &'static str,
    flavor: &str,
    version: &str,
    context: IntegrationFixtureContext<'_>,
    request: Value,
    body: Value,
) -> elasticctl_core::Result<RecordedFixture> {
    let IntegrationFixtureContext {
        active_space,
        nonce,
        expected_inputs,
    } = context;
    let (request, body) = match name {
        "integration_policy_parent_create" => (
            reduce_marker_parent_create_request(&request, nonce)?,
            reduce_marker_parent_create_response(&body, active_space, nonce)?,
        ),
        "integration_policy_create" => (
            reduce_marker_integration_create_request_with_inputs(&request, nonce, expected_inputs)?,
            reduce_marker_integration_response_with_inputs(
                &body,
                active_space,
                nonce,
                &marker_integration_description(nonce),
                expected_inputs,
            )?,
        ),
        "integration_policy_update" => (
            reduce_marker_integration_update_request_with_inputs(&request, nonce, expected_inputs)?,
            reduce_marker_integration_response_with_inputs(
                &body,
                active_space,
                nonce,
                &marker_integration_updated_description(nonce),
                expected_inputs,
            )?,
        ),
        _ => {
            return Err(recording_error(
                "integration policy fixture has no safe exchange reducer",
            ));
        }
    };
    Ok(exchange_fixture(name, flavor, version, request, body))
}

/// Reduce a marker integration response after proving its stable marker
/// identity. The allowlist is intentionally smaller than the public Fleet
/// schema: response-only metadata, active-space references, secrets, and new
/// unknown fields do not prove this recorder's route contract.
fn reduce_marker_integration_response_with_inputs(
    body: &Value,
    active_space: &str,
    nonce: &str,
    expected_description: &str,
    expected_inputs: &Map<String, Value>,
) -> elasticctl_core::Result<Value> {
    let item = body.get("item").and_then(Value::as_object).ok_or_else(|| {
        recording_error("integration policy response must contain an item object")
    })?;
    let package_version = item
        .get("package")
        .and_then(Value::as_object)
        .and_then(|package| package.get("version"))
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            recording_error("integration policy response package version must be non-empty")
        })?;
    let created_description = marker_integration_description(nonce);
    let updated_description = marker_integration_updated_description(nonce);
    let description = if expected_description == created_description {
        INTEGRATION_POLICY_DESCRIPTION
    } else if expected_description == updated_description {
        INTEGRATION_POLICY_UPDATED_DESCRIPTION
    } else {
        return Err(recording_error(
            "integration policy response did not preserve the marker identity",
        ));
    };
    validate_marker_integration_with_nonce_and_inputs(
        body,
        INTEGRATION_POLICY_ID,
        package_version,
        active_space,
        nonce,
        Some(expected_description),
        MarkerIntegrationInputs::Exact(expected_inputs),
    )?;
    Ok(json!({
        "item": {
            "id": INTEGRATION_POLICY_ID,
            "name": INTEGRATION_POLICY_NAME,
            "namespace": INTEGRATION_POLICY_NAMESPACE,
            "description": description,
            "policy_ids": [INTEGRATION_POLICY_PARENT_ID],
            "package": {
                "name": INTEGRATION_POLICY_PACKAGE,
                "version": package_version,
            },
            "inputs": expected_inputs,
            "enabled": true,
        }
    }))
}

fn marker_integration_request_version<'a>(
    request: &'a Value,
    context: &'static str,
) -> elasticctl_core::Result<&'a str> {
    request
        .pointer("/package/version")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| recording_error(format!("{context} package version must be non-empty")))
}

fn reduce_marker_integration_create_request_with_inputs(
    request: &Value,
    nonce: &str,
    expected_inputs: &Map<String, Value>,
) -> elasticctl_core::Result<Value> {
    let version = marker_integration_request_version(request, "integration policy create request")?;
    let expected =
        marker_integration_create_body_with_nonce_and_inputs(version, nonce, expected_inputs);
    if request != &expected {
        return Err(recording_error(
            "integration policy create request did not preserve the exact marker body",
        ));
    }
    let mut reduced = expected;
    reduced["description"] = json!(INTEGRATION_POLICY_DESCRIPTION);
    Ok(reduced)
}

fn reduce_marker_integration_update_request_with_inputs(
    request: &Value,
    nonce: &str,
    expected_inputs: &Map<String, Value>,
) -> elasticctl_core::Result<Value> {
    let version = marker_integration_request_version(request, "integration policy update request")?;
    let expected =
        marker_integration_update_body_with_nonce_and_inputs(version, nonce, expected_inputs);
    if request != &expected {
        return Err(recording_error(
            "integration policy update request did not preserve the exact marker body",
        ));
    }
    let mut reduced = expected;
    reduced["description"] = json!(INTEGRATION_POLICY_UPDATED_DESCRIPTION);
    Ok(reduced)
}

fn reduce_marker_parent_create_request(
    request: &Value,
    nonce: &str,
) -> elasticctl_core::Result<Value> {
    let expected = marker_integration_parent_create_body_with_nonce(nonce);
    if request != &expected {
        return Err(recording_error(
            "integration policy parent create request did not preserve the exact marker body",
        ));
    }
    let mut reduced = expected;
    reduced["description"] = json!(INTEGRATION_POLICY_PARENT_DESCRIPTION);
    Ok(reduced)
}

fn reduce_marker_parent_create_response(
    body: &Value,
    active_space: &str,
    nonce: &str,
) -> elasticctl_core::Result<Value> {
    validate_marker_integration_parent_identity_with_nonce(body, active_space, nonce).map_err(
        |_| {
            recording_error("integration policy parent create did not preserve the marker identity")
        },
    )?;
    Ok(json!({
        "item": {
            "id": INTEGRATION_POLICY_PARENT_ID,
            "name": INTEGRATION_POLICY_PARENT_NAME,
            "namespace": INTEGRATION_POLICY_NAMESPACE,
            "description": INTEGRATION_POLICY_PARENT_DESCRIPTION,
            "monitoring_enabled": [],
            "inactivity_timeout": INTEGRATION_POLICY_PARENT_INACTIVITY_TIMEOUT,
        }
    }))
}

fn reduce_marker_parent_get_response(
    body: &Value,
    active_space: &str,
    nonce: &str,
) -> elasticctl_core::Result<Value> {
    require_parent_attachment_with_nonce(body, active_space, nonce)?;
    let agents = body
        .pointer("/item/agents")
        .and_then(Value::as_u64)
        .ok_or_else(|| {
            recording_error("integration policy parent get agents must be an unsigned integer")
        })?;
    Ok(json!({
        "item": {
            "id": INTEGRATION_POLICY_PARENT_ID,
            "name": INTEGRATION_POLICY_PARENT_NAME,
            "namespace": INTEGRATION_POLICY_NAMESPACE,
            "description": INTEGRATION_POLICY_PARENT_DESCRIPTION,
            "monitoring_enabled": [],
            "inactivity_timeout": INTEGRATION_POLICY_PARENT_INACTIVITY_TIMEOUT,
            "agents": agents,
            "package_policies": [INTEGRATION_POLICY_ID],
        }
    }))
}

fn reduce_marker_integration_list_with_inputs(
    body: &Value,
    active_space: &str,
    nonce: &str,
    expected_inputs: &Map<String, Value>,
) -> elasticctl_core::Result<Value> {
    let items = body
        .get("items")
        .and_then(Value::as_array)
        .filter(|items| items.len() == 1)
        .ok_or_else(|| {
            recording_error("integration policy list must contain exactly one marker item")
        })?;
    let total = body.get("total").and_then(Value::as_u64);
    let page = body.get("page").and_then(Value::as_u64);
    let per_page = body.get("perPage").and_then(Value::as_u64);
    if total != Some(1) || page != Some(1) || per_page != Some(1000) {
        return Err(recording_error(
            "integration policy list did not preserve the exact marker page metadata",
        ));
    }
    let description = marker_integration_description(nonce);
    let reduced = reduce_marker_integration_response_with_inputs(
        &json!({"item": items[0]}),
        active_space,
        nonce,
        &description,
        expected_inputs,
    )?;
    Ok(json!({
        "items": [reduced["item"].clone()],
        "total": 1,
        "page": 1,
        "perPage": 1000,
    }))
}

fn reduce_integration_delete_response(body: &Value) -> elasticctl_core::Result<Value> {
    let item = body
        .as_object()
        .filter(|item| item.len() == 1)
        .filter(|item| item.get("id").and_then(Value::as_str) == Some(INTEGRATION_POLICY_ID))
        .ok_or_else(|| {
            recording_error(
                "integration policy delete response did not contain the exact marker id",
            )
        })?;
    let _ = item;
    Ok(json!({"id": INTEGRATION_POLICY_ID}))
}

fn reduce_parent_delete_response(body: &Value) -> elasticctl_core::Result<Value> {
    let item = body
        .as_object()
        .filter(|item| item.len() == 2)
        .filter(|item| item.get("id").and_then(Value::as_str) == Some(INTEGRATION_POLICY_PARENT_ID))
        .filter(|item| {
            item.get("name").and_then(Value::as_str) == Some(INTEGRATION_POLICY_PARENT_NAME)
        })
        .ok_or_else(|| {
            recording_error(
                "integration policy parent delete response did not contain the exact marker body",
            )
        })?;
    let _ = item;
    Ok(json!({
        "id": INTEGRATION_POLICY_PARENT_ID,
        "name": INTEGRATION_POLICY_PARENT_NAME,
    }))
}

type MetadataVariables = BTreeMap<String, bool>;

struct ReducedMetadataInput {
    key: String,
    vars: MetadataVariables,
    streams: BTreeMap<String, MetadataVariables>,
}

struct ReducedMetadataTemplate {
    name: String,
    data_streams: Option<Vec<String>>,
    selected_datasets: BTreeSet<String>,
    inputs: BTreeMap<String, ReducedMetadataInput>,
}

/// The package registry exposes a broad, deployment-specific document. The
/// recorder accepts its schema only after reducing it to the exact fields the
/// integration-policy secret classifier needs. The structural checks mirror
/// the production secret parser so an ambiguous public fixture never becomes
/// a more permissive test input than a live package response.
fn reduce_integration_package_metadata(
    body: &Value,
    expected_name: &str,
    expected_version: &str,
) -> elasticctl_core::Result<Value> {
    let item = body
        .get("item")
        .and_then(Value::as_object)
        .ok_or_else(|| recording_error("package metadata must contain an item object"))?;
    let name = metadata_nonempty_string(item, "name", "package metadata")?;
    let version = metadata_nonempty_string(item, "version", "package metadata")?;
    if name != expected_name || version != expected_version {
        return Err(recording_error(
            "package metadata did not preserve the requested exact coordinate",
        ));
    }
    let status = metadata_nonempty_string(item, "status", "package metadata")?;
    if !matches!(status.as_str(), "installed" | "not_installed") {
        return Err(recording_error(
            "package metadata status must be installed or not_installed",
        ));
    }

    let vars = reduce_metadata_variables(item.get("vars"), "package metadata vars")?;
    let modern_datasets = reduce_metadata_data_streams(item.get("data_streams"))?;
    let templates = match item.get("policy_templates") {
        None => &[][..],
        Some(Value::Array(templates)) => templates.as_slice(),
        Some(_) => {
            return Err(recording_error(
                "package metadata policy_templates must be an array",
            ));
        }
    };

    let mut template_names = BTreeSet::new();
    let mut input_keys = BTreeSet::new();
    let mut legacy_streams = BTreeMap::new();
    let mut reduced_templates = Vec::with_capacity(templates.len());
    for template in templates {
        let template = template.as_object().ok_or_else(|| {
            recording_error("package metadata policy_templates entries must be objects")
        })?;
        let template_name = metadata_nonempty_string(template, "name", "policy template")?;
        if !template_names.insert(template_name.clone()) {
            return Err(recording_error(
                "package metadata contains duplicate policy template names",
            ));
        }
        let (data_streams, selected_datasets) = reduce_metadata_template_data_streams(
            template.get("data_streams"),
            &modern_datasets,
            &name,
        )?;
        let inputs = match template.get("inputs") {
            None => &[][..],
            Some(Value::Array(inputs)) => inputs.as_slice(),
            Some(_) => {
                return Err(recording_error(
                    "package metadata policy template inputs must be an array",
                ));
            }
        };
        let mut reduced_inputs = BTreeMap::new();
        for input in inputs {
            let input = input.as_object().ok_or_else(|| {
                recording_error("package metadata policy template inputs must be objects")
            })?;
            let input_type = metadata_nonempty_string(input, "type", "policy template input")?;
            let input_key = format!("{template_name}-{input_type}");
            if !input_keys.insert(input_key.clone()) {
                return Err(recording_error(
                    "package metadata contains duplicate template input definitions",
                ));
            }
            let input_vars =
                reduce_metadata_variables(input.get("vars"), "package metadata input vars")?;
            let streams = match input.get("streams") {
                None => &[][..],
                Some(Value::Array(streams)) => streams.as_slice(),
                Some(_) => {
                    return Err(recording_error(
                        "package metadata input streams must be an array",
                    ));
                }
            };
            let mut reduced_streams = BTreeMap::new();
            for stream in streams {
                let stream = stream.as_object().ok_or_else(|| {
                    recording_error("package metadata input streams must be objects")
                })?;
                let data_stream = stream
                    .get("data_stream")
                    .and_then(Value::as_object)
                    .ok_or_else(|| {
                        recording_error("package metadata stream data_stream must be an object")
                    })?;
                let dataset = metadata_nonempty_string(
                    data_stream,
                    "dataset",
                    "package metadata stream data_stream",
                )?;
                let stream_vars =
                    reduce_metadata_variables(stream.get("vars"), "package metadata stream vars")?;
                if reduced_streams
                    .insert(dataset.clone(), stream_vars.clone())
                    .is_some()
                    || legacy_streams
                        .insert((input_key.clone(), dataset), stream_vars)
                        .is_some()
                {
                    return Err(recording_error(
                        "package metadata contains duplicate legacy stream definitions",
                    ));
                }
            }
            if reduced_inputs
                .insert(
                    input_type,
                    ReducedMetadataInput {
                        key: input_key,
                        vars: input_vars,
                        streams: reduced_streams,
                    },
                )
                .is_some()
            {
                return Err(recording_error(
                    "package metadata contains duplicate policy template input types",
                ));
            }
        }
        reduced_templates.push(ReducedMetadataTemplate {
            name: template_name,
            data_streams,
            selected_datasets,
            inputs: reduced_inputs,
        });
    }
    reduced_templates.sort_by(|left, right| left.name.cmp(&right.name));

    let mut modern_streams = BTreeMap::new();
    for (dataset, streams) in &modern_datasets {
        for (input_type, stream_vars) in streams {
            let candidates = reduced_templates
                .iter()
                .filter(|template| template.selected_datasets.contains(dataset))
                .filter_map(|template| template.inputs.get(input_type))
                .map(|input| input.key.clone())
                .collect::<Vec<_>>();
            let input_key = match candidates.as_slice() {
                [input_key] => input_key.clone(),
                [] => {
                    return Err(recording_error(
                        "package metadata modern stream has no matching template input",
                    ));
                }
                _ => {
                    return Err(recording_error(
                        "package metadata modern stream has multiple matching template inputs",
                    ));
                }
            };
            if modern_streams
                .insert((input_key, dataset.clone()), stream_vars.clone())
                .is_some()
            {
                return Err(recording_error(
                    "package metadata contains duplicate modern stream definitions",
                ));
            }
        }
    }
    for (key, legacy_vars) in legacy_streams {
        match modern_streams.get(&key) {
            Some(modern_vars) if modern_vars != &legacy_vars => {
                return Err(recording_error(
                    "package metadata has conflicting modern and legacy stream definitions",
                ));
            }
            Some(_) => {}
            None => {
                modern_streams.insert(key, legacy_vars);
            }
        }
    }

    let policy_templates = Value::Array(
        reduced_templates
            .into_iter()
            .map(|template| {
                let inputs = Value::Array(
                    template
                        .inputs
                        .into_iter()
                        .map(|(input_type, input)| {
                            let streams = Value::Array(
                                input
                                    .streams
                                    .into_iter()
                                    .map(|(dataset, vars)| {
                                        json!({
                                            "data_stream": {"dataset": dataset},
                                            "vars": metadata_variables_value(&vars),
                                        })
                                    })
                                    .collect(),
                            );
                            json!({
                                "type": input_type,
                                "vars": metadata_variables_value(&input.vars),
                                "streams": streams,
                            })
                        })
                        .collect(),
                );
                let mut reduced = json!({"name": template.name, "inputs": inputs});
                if let Some(data_streams) = template.data_streams {
                    reduced
                        .as_object_mut()
                        .expect("reduced template is an object")
                        .insert(
                            "data_streams".into(),
                            Value::Array(data_streams.into_iter().map(Value::String).collect()),
                        );
                }
                reduced
            })
            .collect(),
    );
    let data_streams = Value::Array(
        modern_datasets
            .into_iter()
            .map(|(dataset, streams)| {
                let streams = Value::Array(
                    streams
                        .into_iter()
                        .map(|(input, vars)| {
                            json!({
                                "input": input,
                                "vars": metadata_variables_value(&vars),
                            })
                        })
                        .collect(),
                );
                json!({"dataset": dataset, "streams": streams})
            })
            .collect(),
    );

    Ok(json!({
        "item": {
            "name": name,
            "version": version,
            "status": status,
            "vars": metadata_variables_value(&vars),
            "policy_templates": policy_templates,
            "data_streams": data_streams,
        }
    }))
}

fn metadata_nonempty_string(
    object: &serde_json::Map<String, Value>,
    field: &str,
    context: &str,
) -> elasticctl_core::Result<String> {
    object
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .ok_or_else(|| recording_error(format!("{context} {field} must be a non-empty string")))
}

fn reduce_metadata_variables(
    value: Option<&Value>,
    context: &str,
) -> elasticctl_core::Result<MetadataVariables> {
    let values = match value {
        None => return Ok(MetadataVariables::new()),
        Some(Value::Array(values)) => values,
        Some(_) => return Err(recording_error(format!("{context} must be an array"))),
    };
    let mut reduced = MetadataVariables::new();
    for value in values {
        let variable = value
            .as_object()
            .ok_or_else(|| recording_error(format!("{context} entries must be objects")))?;
        let name = metadata_nonempty_string(variable, "name", context)?;
        let secret = match variable.get("secret") {
            None => false,
            Some(Value::Bool(secret)) => *secret,
            Some(_) => {
                return Err(recording_error(format!(
                    "{context} secret must be a boolean"
                )));
            }
        };
        if reduced.insert(name, secret).is_some() {
            return Err(recording_error(format!(
                "{context} contains duplicate variable definitions"
            )));
        }
    }
    Ok(reduced)
}

fn metadata_variables_value(vars: &MetadataVariables) -> Value {
    Value::Array(
        vars.iter()
            .map(|(name, secret)| json!({"name": name, "secret": secret}))
            .collect(),
    )
}

fn reduce_metadata_data_streams(
    value: Option<&Value>,
) -> elasticctl_core::Result<BTreeMap<String, BTreeMap<String, MetadataVariables>>> {
    let data_streams = match value {
        None => &[][..],
        Some(Value::Array(data_streams)) => data_streams.as_slice(),
        Some(_) => {
            return Err(recording_error(
                "package metadata data_streams must be an array",
            ));
        }
    };
    let mut reduced = BTreeMap::new();
    for data_stream in data_streams {
        let data_stream = data_stream.as_object().ok_or_else(|| {
            recording_error("package metadata data_streams entries must be objects")
        })?;
        let dataset =
            metadata_nonempty_string(data_stream, "dataset", "package metadata data_stream")?;
        let streams = match data_stream.get("streams") {
            None => &[][..],
            Some(Value::Array(streams)) => streams.as_slice(),
            Some(_) => {
                return Err(recording_error(
                    "package metadata data_streams streams must be an array",
                ));
            }
        };
        let mut reduced_streams = BTreeMap::new();
        for stream in streams {
            let stream = stream.as_object().ok_or_else(|| {
                recording_error("package metadata data_streams streams entries must be objects")
            })?;
            let input =
                metadata_nonempty_string(stream, "input", "package metadata data_streams stream")?;
            let vars =
                reduce_metadata_variables(stream.get("vars"), "package metadata stream vars")?;
            if reduced_streams.insert(input, vars).is_some() {
                return Err(recording_error(
                    "package metadata data_streams contains duplicate stream inputs",
                ));
            }
        }
        if reduced.insert(dataset, reduced_streams).is_some() {
            return Err(recording_error(
                "package metadata contains duplicate data stream datasets",
            ));
        }
    }
    Ok(reduced)
}

fn reduce_metadata_template_data_streams(
    value: Option<&Value>,
    datasets: &BTreeMap<String, BTreeMap<String, MetadataVariables>>,
    package_name: &str,
) -> elasticctl_core::Result<(Option<Vec<String>>, BTreeSet<String>)> {
    let Some(value) = value else {
        return Ok((None, datasets.keys().cloned().collect()));
    };
    let selectors = value.as_array().ok_or_else(|| {
        recording_error("package metadata template data_streams must be an array")
    })?;
    let mut raw_selectors = BTreeSet::new();
    let mut selected_datasets = BTreeSet::new();
    for selector in selectors {
        let selector = selector
            .as_str()
            .filter(|selector| !selector.trim().is_empty())
            .ok_or_else(|| {
                recording_error(
                    "package metadata template data_streams selector must be a non-empty string",
                )
            })?;
        if !raw_selectors.insert(selector.to_owned()) {
            return Err(recording_error(
                "package metadata template contains duplicate data_streams selectors",
            ));
        }
        let short_name = format!("{package_name}.{selector}");
        let candidates = datasets
            .keys()
            .filter(|dataset| dataset.as_str() == selector || dataset.as_str() == short_name)
            .collect::<Vec<_>>();
        let dataset = match candidates.as_slice() {
            [dataset] => *dataset,
            [] => {
                return Err(recording_error(
                    "package metadata template data_streams selector does not match a dataset",
                ));
            }
            _ => {
                return Err(recording_error(
                    "package metadata template data_streams selector matches multiple datasets",
                ));
            }
        };
        if !selected_datasets.insert(dataset.clone()) {
            return Err(recording_error(
                "package metadata template contains duplicate selected data streams",
            ));
        }
    }
    Ok((Some(raw_selectors.into_iter().collect()), selected_datasets))
}

/// Decode an installed-package inventory into memory-only coordinates. Fleet
/// returns the last-item sort cursor even when the fixed one-page request is
/// complete, so completeness comes from the total and item count instead.
fn decode_installed_package_inventory(
    body: &Value,
) -> elasticctl_core::Result<BTreeSet<(String, String)>> {
    let envelope = body
        .as_object()
        .ok_or_else(|| recording_error("installed package inventory must be an object"))?;
    for key in envelope.keys() {
        if !matches!(
            key.as_str(),
            "items" | "total" | "searchAfter" | "searchExcluded"
        ) {
            return Err(recording_error(
                "installed package inventory contains an unknown envelope field",
            ));
        }
    }
    let items = envelope
        .get("items")
        .and_then(Value::as_array)
        .ok_or_else(|| recording_error("installed package inventory items must be an array"))?;
    let total = envelope
        .get("total")
        .and_then(Value::as_u64)
        .ok_or_else(|| recording_error("installed package inventory total must be unsigned"))?;
    if total > 1000 {
        return Err(recording_error(
            "installed package inventory total exceeds the one-page limit",
        ));
    }
    if items.len() as u64 != total {
        return Err(recording_error(
            "installed package inventory item count does not match total",
        ));
    }
    if let Some(cursor) = envelope.get("searchAfter") {
        let valid = matches!(cursor, Value::Array(values)
        if values.len() <= 2
            && values.iter().all(|value| {
                value.is_string() || value.is_number() || value.is_boolean()
            }));
        if !valid {
            return Err(recording_error(
                "installed package inventory searchAfter must contain at most two scalar sort values",
            ));
        }
    }
    if let Some(search_excluded) = envelope.get("searchExcluded")
        && search_excluded.as_u64() != Some(0)
    {
        return Err(recording_error(
            "installed package inventory searchExcluded must be unsigned zero",
        ));
    }

    let mut names = BTreeSet::new();
    let mut coordinates = BTreeSet::new();
    for item in items {
        let item = item
            .as_object()
            .ok_or_else(|| recording_error("installed package inventory items must be objects"))?;
        let name = metadata_nonempty_string(item, "name", "installed package inventory item")?;
        if item.get("status").and_then(Value::as_str) != Some("installed") {
            return Err(recording_error(
                "installed package inventory item status must be installed",
            ));
        }
        let version =
            metadata_nonempty_string(item, "version", "installed package inventory item")?;
        if !names.insert(name.clone()) || !coordinates.insert((name, version)) {
            return Err(recording_error(
                "installed package inventory contains duplicate package coordinates",
            ));
        }
    }
    Ok(coordinates)
}

fn require_matching_inventory(
    baseline: &BTreeSet<(String, String)>,
    current: &BTreeSet<(String, String)>,
) -> elasticctl_core::Result<()> {
    if baseline == current {
        Ok(())
    } else {
        Err(recording_error(
            "installed package inventory differs from the recording baseline",
        ))
    }
}

#[derive(Clone, Debug)]
struct SystemPackageStatus {
    registry_version: String,
    version: String,
    installed: bool,
}

fn decode_system_package_status(body: &Value) -> elasticctl_core::Result<SystemPackageStatus> {
    let item = body
        .get("item")
        .and_then(Value::as_object)
        .ok_or_else(|| recording_error("system package status must contain an item object"))?;
    if metadata_nonempty_string(item, "name", "system package status")?
        != INTEGRATION_POLICY_PACKAGE
    {
        return Err(recording_error(
            "system package status did not name the system package",
        ));
    }
    let registry_version = metadata_nonempty_string(item, "version", "system package status")?;
    match item.get("status").and_then(Value::as_str) {
        Some("installed") => {
            let installation = item
                .get("installationInfo")
                .and_then(Value::as_object)
                .ok_or_else(|| {
                    recording_error("installed system package status lacks installationInfo")
                })?;
            let version = metadata_nonempty_string(
                installation,
                "version",
                "installed system package status",
            )?;
            Ok(SystemPackageStatus {
                registry_version,
                version,
                installed: true,
            })
        }
        Some("not_installed") => {
            if !matches!(item.get("installationInfo"), None | Some(Value::Null)) {
                return Err(recording_error(
                    "not_installed system package status has installationInfo",
                ));
            }
            Ok(SystemPackageStatus {
                version: registry_version.clone(),
                registry_version,
                installed: false,
            })
        }
        _ => Err(recording_error(
            "system package status must be installed or not_installed",
        )),
    }
}

/// `package_system` is an integration-recorder-only fixture. Build it solely
/// from the strict status decoder so registry metadata such as `latestVersion`
/// never reaches a public fixture.
fn reduce_system_package_status(status: &SystemPackageStatus) -> Value {
    let mut item = json!({
        "name": INTEGRATION_POLICY_PACKAGE,
        "version": status.registry_version,
        "status": if status.installed { "installed" } else { "not_installed" },
    });
    if status.installed {
        item["installationInfo"] = json!({"version": status.version});
    }
    item
}

async fn read_installed_package_inventory(
    t: &elasticctl_core::Transport,
) -> elasticctl_core::Result<BTreeSet<(String, String)>> {
    let body = t.get(INSTALLED_PACKAGE_INVENTORY_PATH).await?;
    decode_installed_package_inventory(&body)
}

async fn require_unchanged_installed_package_inventory(
    t: &elasticctl_core::Transport,
    baseline: &BTreeSet<(String, String)>,
    context: &'static str,
) -> elasticctl_core::Result<()> {
    let current = read_installed_package_inventory(t)
        .await
        .map_err(|error| safe_recording_transport_error(context, error))?;
    require_matching_inventory(baseline, &current)
}

fn combine_package_policy_attempt_and_inventory_errors(
    attempt_context: &'static str,
    attempt: &elasticctl_core::Error,
    observation: &elasticctl_core::Error,
) -> elasticctl_core::Error {
    recording_error(format!(
        "{attempt_context}: {}; installed package inventory observation also failed: {}",
        safe_recording_error_summary(attempt),
        safe_recording_error_summary(observation),
    ))
}

fn marker_integration_parent_create_body_with_nonce(nonce: &str) -> Value {
    json!({
        "id": INTEGRATION_POLICY_PARENT_ID,
        "name": INTEGRATION_POLICY_PARENT_NAME,
        "namespace": INTEGRATION_POLICY_NAMESPACE,
        "description": marker_integration_parent_description(nonce),
        "monitoring_enabled": [],
        "inactivity_timeout": INTEGRATION_POLICY_PARENT_INACTIVITY_TIMEOUT,
    })
}

fn marker_integration_create_body_with_nonce(version: &str, nonce: &str) -> Value {
    marker_integration_create_body_with_nonce_and_inputs(version, nonce, &Map::new())
}

fn marker_integration_create_body_with_nonce_and_inputs(
    version: &str,
    nonce: &str,
    inputs: &Map<String, Value>,
) -> Value {
    json!({
        "id": INTEGRATION_POLICY_ID,
        "name": INTEGRATION_POLICY_NAME,
        "description": marker_integration_description(nonce),
        "namespace": INTEGRATION_POLICY_NAMESPACE,
        "policy_ids": [INTEGRATION_POLICY_PARENT_ID],
        "package": {"name": INTEGRATION_POLICY_PACKAGE, "version": version},
        "inputs": inputs,
    })
}

#[cfg(test)]
fn marker_integration_update_body_with_nonce(version: &str, nonce: &str) -> Value {
    marker_integration_update_body_with_nonce_and_inputs(version, nonce, &Map::new())
}

fn marker_integration_update_body_with_nonce_and_inputs(
    version: &str,
    nonce: &str,
    inputs: &Map<String, Value>,
) -> Value {
    let mut body = marker_integration_create_body_with_nonce_and_inputs(version, nonce, inputs);
    let object = body
        .as_object_mut()
        .expect("marker integration body is an object");
    object.remove("id");
    object.insert(
        "description".to_string(),
        json!(marker_integration_updated_description(nonce)),
    );
    object.insert("enabled".to_string(), Value::Bool(true));
    body
}

fn sensitive_marker_input_field(name: &str) -> bool {
    let name = name.to_ascii_lowercase();
    [
        "secret",
        "password",
        "passphrase",
        "token",
        "credential",
        "api_key",
        "apikey",
        "private_key",
        "access_key",
    ]
    .iter()
    .any(|needle| name.contains(needle))
}

/// Inspect only input-map field names and container structure. Values never
/// participate in this recorder-side backstop; the production export path is
/// the authority for secret classification.
fn marker_inputs_have_sensitive_field_names(value: &Value) -> bool {
    match value {
        Value::Object(fields) => fields.iter().any(|(name, value)| {
            sensitive_marker_input_field(name) || marker_inputs_have_sensitive_field_names(value)
        }),
        Value::Array(values) => values.iter().any(marker_inputs_have_sensitive_field_names),
        _ => false,
    }
}

fn exported_marker_optional_fields_are_empty(
    spec: &elasticctl_api::fleet::integration_policies::IntegrationPolicySpec,
) -> bool {
    spec.vars.as_ref().is_none_or(Map::is_empty)
        && spec.var_group_selections.as_ref().is_none_or(Map::is_empty)
        && spec.condition.as_deref().is_none_or(str::is_empty)
        && spec
            .additional_datastreams_permissions
            .as_ref()
            .is_none_or(Vec::is_empty)
}

fn capture_exported_bootstrap_inputs(
    spec: elasticctl_api::fleet::integration_policies::IntegrationPolicySpec,
    expected_version: &str,
    nonce: &str,
    bootstrap_item: &Map<String, Value>,
    active_space: &str,
) -> elasticctl_core::Result<Map<String, Value>> {
    let expected_description = marker_integration_description(nonce);
    let identity_matches = spec.id == INTEGRATION_POLICY_ID
        && spec.name == INTEGRATION_POLICY_NAME
        && spec.namespace.as_deref() == Some(INTEGRATION_POLICY_NAMESPACE)
        && spec.policy_ids == [INTEGRATION_POLICY_PARENT_ID]
        && spec.package.name == INTEGRATION_POLICY_PACKAGE
        && spec.package.version == expected_version
        && spec.description.as_deref() == Some(expected_description.as_str())
        && !spec.inputs.is_empty()
        && exported_marker_optional_fields_are_empty(&spec);
    if !identity_matches {
        return Err(recording_error(
            "exported bootstrap integration policy did not preserve the marker identity",
        ));
    }
    if marker_inputs_have_sensitive_field_names(&Value::Object(spec.inputs.clone())) {
        return Err(recording_error(
            "exported bootstrap integration policy contained sensitive-looking input fields",
        ));
    }
    let normalized =
        elasticctl_api::fleet::integration_policy_ops::normalize(bootstrap_item, active_space)
            .map_err(|_| recording_error("normalizing bootstrap integration policy failed"))?;
    if normalized.inputs != spec.inputs {
        return Err(recording_error(
            "exported bootstrap integration policy inputs did not match the marker read",
        ));
    }
    Ok(spec.inputs)
}

async fn export_bootstrap_marker_inputs(
    t: &elasticctl_core::Transport,
    expected_version: &str,
    nonce: &str,
    bootstrap_item: &Map<String, Value>,
) -> elasticctl_core::Result<Map<String, Value>> {
    let selectors = vec![INTEGRATION_POLICY_ID.to_owned()];
    let exported = elasticctl_api::fleet::integration_policy_ops::export(
        t,
        &selectors,
        false,
        elasticctl_api::content_codec::ContentFormat::Json,
    )
    .await
    .map_err(|_| recording_error("exporting bootstrap integration policy failed"))?;
    let spec = decode_exported_bootstrap_marker(exported)?;
    capture_exported_bootstrap_inputs(spec, expected_version, nonce, bootstrap_item, t.space())
}

fn decode_exported_bootstrap_marker(
    exported: elasticctl_api::ops::ExportOutcome,
) -> elasticctl_core::Result<elasticctl_api::fleet::integration_policies::IntegrationPolicySpec> {
    let mut specs = elasticctl_api::content_codec::decode_sequence::<
        elasticctl_api::fleet::integration_policies::IntegrationPolicySpec,
    >(
        &exported.body,
        elasticctl_api::content_codec::ContentFormat::Json,
        "integration policy",
    )
    .map_err(|_| recording_error("decoding exported bootstrap integration policy failed"))?;
    if exported.exported != 1 || !exported.missing.is_empty() || specs.len() != 1 {
        return Err(recording_error(
            "exporting bootstrap integration policy did not return exactly one marker",
        ));
    }
    Ok(specs
        .pop()
        .expect("one exported integration policy was checked"))
}

