        Mock::given(method("GET"))
            .and(path("/api/detection_engine/rules/prepackaged/_status"))
            .respond_with(
                ResponseTemplate::new(503).set_body_json(json!({"message": "private-status-body"})),
            )
            .expect(3)
            .mount(&server)
            .await;

